CREATE OR REPLACE FUNCTION public.chat_state()
 RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$ DECLARE u uuid:=auth.uid(); BEGIN IF u IS NULL THEN RAISE EXCEPTION 'يجب تسجيل الدخول'; END IF; RETURN jsonb_build_object('friendships',coalesce((SELECT jsonb_agg(x ORDER BY x.updated_at DESC) FROM (SELECT f.*,p.username,p.display_name,p.avatar_url,p.id AS peer_id,CASE WHEN coalesce(s.hide_presence,false) THEN NULL ELSE p.last_seen_at END AS last_seen_at,CASE WHEN coalesce(s.hide_presence,false) THEN false ELSE p.is_online AND p.last_seen_at>now()-interval '30 seconds' END AS is_online,coalesce(s.hide_presence,false) AS presence_hidden,EXISTS(SELECT 1 FROM public.chat_blocks b WHERE b.blocker_id=u AND b.blocked_id=p.id) AS blocked_by_me,EXISTS(SELECT 1 FROM public.chat_blocks b WHERE b.blocker_id=p.id AND b.blocked_id=u) AS blocked_by_peer,(SELECT body FROM public.chat_messages m WHERE m.friendship_id=f.id AND m.created_at>now()-interval '3 days' AND m.created_at>coalesce(c.cleared_at,'-infinity') ORDER BY created_at DESC LIMIT 1) AS last_body,(SELECT max(created_at) FROM public.chat_messages m WHERE m.friendship_id=f.id AND m.created_at>now()-interval '3 days' AND m.created_at>coalesce(c.cleared_at,'-infinity')) AS last_message_at,(SELECT count(*) FROM public.chat_messages m WHERE m.friendship_id=f.id AND m.created_at>now()-interval '3 days' AND m.created_at>coalesce(c.cleared_at,'-infinity') AND m.sender_id<>u AND m.read_at IS NULL AND m.deleted_at IS NULL) AS unread FROM public.chat_friendships f JOIN public.profiles p ON p.id=CASE WHEN f.requester_id=u THEN f.recipient_id ELSE f.requester_id END LEFT JOIN public.chat_preferences s ON s.user_id=p.id LEFT JOIN public.chat_history_clears c ON c.user_id=u AND c.friendship_id=f.id WHERE u IN(f.requester_id,f.recipient_id)) x),'[]'::jsonb)); END $function$;